import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import Navbar from "./components/Navbar";
import Footer from "./components/Footer";
import Landing from "./components/pages/Landing";
import Home from "./components/pages/Home";
import Interview from "./components/pages/Interview";
import Feedback from "./components/pages/Feedback";
import Login from "./components/pages/Login";
import Signup from "./components/pages/Signup";

function App() {
  const [loggedIn, setLoggedIn] = useState(false);
  const [visitedHome, setVisitedHome] = useState(false);
  const [interviewDone, setInterviewDone] = useState(false);

  return (
    <Router>
      <div className="flex flex-col min-h-screen bg-gradient-to-br from-blue-900 via-blue-800 to-blue-900 text-white">
        <Navbar
          loggedIn={loggedIn}
          setLoggedIn={setLoggedIn}
          visitedHome={visitedHome}
          interviewDone={interviewDone}
        />

        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Landing />} />
            <Route path="/login" element={<Login setLoggedIn={setLoggedIn} />} />
            <Route path="/signup" element={<Signup setLoggedIn={setLoggedIn} />} />

            <Route
              path="/home"
              element={
                loggedIn ? (
                  <Home setVisitedHome={setVisitedHome} />
                ) : (
                  <Navigate to="/login" />
                )
              }
            />

            <Route
              path="/interview"
              element={
                loggedIn && visitedHome ? (
                  <Interview setInterviewDone={setInterviewDone} />
                ) : (
                  <Navigate to="/home" />
                )
              }
            />

            <Route
              path="/feedback"
              element={
                loggedIn && visitedHome && interviewDone ? (
                  <Feedback />
                ) : (
                  <Navigate to="/home" />
                )
              }
            />
          </Routes>
        </main>

        <Footer />
      </div>
    </Router>
  );
}

export default App;
